goal_min=goal['min_count']
goal_max=goal['max_count']
goal_sum_bounds=goal['sum_bounds']
goal_unique=goal['unique']
goal_order=goal['order_by']
result=None
for k in range(goal_min,goal_max+1):
 for combo in combinations(options,k):
  ids=[opt['id'] for opt in combo]
  owners=[opt['owner'] for opt in combo]
  if len(set(owners))!=len(owners):
   continue
  total_quality=0
  total_cost=0
  for opt in combo:
   total_quality=total_quality+opt['quality']
   total_cost=total_cost+opt['cost']
  if 'quality' in goal_sum_bounds:
   if 'min' in goal_sum_bounds['quality']:
    if total_quality<goal_sum_bounds['quality']['min']:
     continue
  if 'cost' in goal_sum_bounds:
   if 'max' in goal_sum_bounds['cost']:
    if total_cost>goal_sum_bounds['cost']['max']:
     continue
  # no_conflicts false means conflicts allowed, so skip conflict check
  # closed_dependencies false means no requires check
  # cover empty means no coverage check
  sorted_combo=sorted(combo,key=lambda x:(x['rank'],x['id']))
  sorted_ids=[opt['id'] for opt in sorted_combo]
  if sorted_ids!=ids:
   continue
  if valid(ids):
   result=ids
   break
 if result is not None:
